import {physicalActorsForMap} from './physical-actors.mjs';
import {SpeciesCatalogService} from '../species-catalog-service.mjs';
import {createEconomyGame} from '../economy/session.mjs';
import {candidateAdapter} from '../economy/candidate.mjs';
import {CANDIDATE_ID,activeEconomyPolicy,quotePurchase} from '../economy/contract.mjs';
import {StoryProgressionService} from '../story/progression-service.mjs';
import {createStoryFieldHooks} from '../story/field-bridge.mjs';
import {createFieldCore,coreWalkable,vector,tickFieldCore,fieldInputLocked,endNPCDialogue,unlockField} from '../field-engine-core.mjs';
import {registerPlayableTileMap} from '../field-behavior.mjs';
import {createFieldAnimation} from '../field-animation.mjs';
import {bindCoreSpatial} from './core-spatial.mjs';
import {createWorldDefinition,GRID,cellPosition,positionCell,pointDistance,zoneAt,tileAt} from './definition.mjs';
import {initialWorldState,adoptPlacementPosition,worldStageAccess,worldWalkable,worldGate,validateWorldLocation} from './state.mjs';
export function createWorldHost(def,story){const host={world:def,story,developmentOnly:true,initialHub:def.initialHub,hubs:{},points:{}};
 host.canOccupy=(s,id,x,y,opts={})=>worldWalkable(def,s,id,x,y,{story,...opts,actors:false})&&(opts.actors===false||!physicalActorsForMap(def,id,s,story).some(actor=>actor.x===x&&actor.y===y));
 host.validLanding=(p,s)=>{if(!s||!p||!Number.isFinite(p.x)||!Number.isFinite(p.y))return false;const c=positionCell(p),m=def.maps[p.scene];return !!m&&worldStageAccess(s,story,m.stageId)&&host.canOccupy(s,p.scene,c.x,c.y,{surf:false})&&!['WARP','DOOR','LEDGE','WATER','WATER_EDGE'].includes(tileAt(m,c.x,c.y).name)};
 host.canInteract=(a,b)=>a.scene===b.scene&&Math.abs(a.x-b.x)+Math.abs(a.y-b.y)<=GRID;
 for(const p of Object.values(def.points)){if(p.hubId)host.hubs[p.hubId]={id:p.hubId,position:cellPosition(p.mapId,p.x,p.y),stageId:p.stageId};if(p.kind==='research')host.points[p.id]={id:p.id,position:cellPosition(p.mapId,p.x,p.y)}}return host;
}
/** Spatial adapter only; canonical Story/Battle/Encounter own every gameplay transaction. */
export class CanonicalWorld{
 constructor({adapter,runtime=null,mode='development',starterId='SPECIES_001',playerName='탐험가',appearance='boy',candidate=false,persist=null,hooks={},rng=Math.random,battleDriver=null,encounterEnvironment=null,encounterDiagnostic=null}){
  this.adapter=candidate?candidateAdapter(adapter,{mode,policyId:CANDIDATE_ID}):adapter;this.catalog=new SpeciesCatalogService({namespace:'canonical',adapter:this.adapter});this.definition=createWorldDefinition(this.adapter);this.host=createWorldHost(this.definition,this.catalog.encounterContract.story);this.rng=rng;this.battleDriver=battleDriver;this.pending=false;this.animation=createFieldAnimation();
  let save=runtime??createEconomyGame(this.catalog,{mode,starterId,playerName,appearance});if(runtime&&!runtime.world)throw Error('World save required; existing saves not automatically relocated');if(!runtime){save.world=initialWorldState(this.definition);save.position=structuredClone(this.definition.initialPosition)}save=adoptPlacementPosition(save,this.host);validateWorldLocation(save,this.host);
  for(const m of Object.values(this.definition.maps))registerPlayableTileMap(m.id,{tiles:m.tiles,name:m.label,worldTileSize:GRID});
  this.field={...save.position,walk:0,moving:false,menu:null,dialogue:[],dialogueIndex:0,transition:null,core:createFieldCore()};
  this.disposer=bindCoreSpatial(this.field,{walkable:(id,x,y)=>this.host.canOccupy(this.snapshot(),id,Math.floor(x/GRID),Math.floor(y/GRID),{actors:false}),sightBlocked:(id,x,y)=>!this.host.canOccupy(this.snapshot(),id,Math.floor(x/GRID),Math.floor(y/GRID),{actors:false,surf:false})});
  const base=createStoryFieldHooks(this.field,{dialogue:hooks.dialogue??(()=>{}),cutIn:hooks.cutIn??(()=>{}),nextFrame:hooks.nextFrame??(async()=>{})});
  this.story=new StoryProgressionService({runtime:save,catalog:this.catalog,adapter:this.adapter,economyHost:this.host,persist,encounterEnvironment,encounterDiagnostic,hooks:{...base,inputLock:()=>{if(this.field.core.pendingBattle)this.field.core.lock='canonical-story';base.inputLock()},cameraCue:op=>this.field.core.pendingBattle&&this.field.core.battleReady?undefined:base.cameraCue(op),battleReady:hooks.battleReady,battleFinished:outcome=>{base.battleFinished(outcome);hooks.battleFinished?.(outcome)}}});this.syncField(true);
 }
 get busy(){return this.pending||this.story.busy||this.story.pendingCommit}
 // User commands share one lock; the owned detected-battle handoff is the sole exception.
 get inputLocked(){return !!(this.busy||fieldInputLocked(this.field)||this.field.core.lock||this.field.core.sequence||this.field.core.pendingBattle||this.field.dialogue.length)}
 snapshot(){return this.story.snapshot()} get map(){return this.definition.maps[this.field.scene]}
 syncField(reset=false){const s=this.snapshot(),changed=this.field.scene!==s.position.scene;Object.assign(this.field,s.position);const actors=physicalActorsForMap(this.definition,this.map.id,s,this.story.contract),physicalChanged=actors.length!==this.field.core.npcs.length||actors.some((actor,i)=>actor.id!==this.field.core.npcs[i]?.id);if(reset||changed||physicalChanged)this.field.core.npcs=actors.map(a=>{const p=this.definition.points[a.pointId],pos=cellPosition(this.map.id,a.x,a.y);return {id:a.id,pointId:a.pointId,canonicalNpcId:a.npcId,canonicalTrainerId:a.trainerId,map:this.map.id,x:pos.x,y:pos.y,homeX:pos.x,homeY:pos.y,facing:a.facing,homeFacing:a.facing,movement:'FACE_FIXED',wait:1600,target:null,waypoints:[],waypoint:0,range:0,walk:0,moving:false,paused:false,trainer:p.kind==='trainer',sightRange:3,defeated:false,sightCooldown:0,battleId:p.trainerId??'',dialogue:p.label,afterDialogue:'조사를 응원해요.',action:'',body:[-18,-18,36,36],sprite:'player-atlas',fieldAssetId:a.fieldAssetId}});for(const n of this.field.core.npcs){n.trainer=!!n.canonicalTrainerId&&this.story.trainerAvailable(n.canonicalTrainerId);n.defeated=!!n.canonicalTrainerId&&s.progress.defeatedTrainers.includes(n.canonicalTrainerId)}}
 options(extra={}){return {rng:this.rng,battleDriver:this.battleDriver,map:this.map,...extra}}
 async operation(fn,{resetActors=false,allowFieldSequence=false}={}){if(this.busy)throw Error('WORLD_BUSY');if(!allowFieldSequence&&this.inputLocked)throw Error('WORLD_INPUT_LOCKED');this.pending=true;try{return await fn()}finally{this.pending=false;this.syncField(resetActors)}}
 async move(facing){if(fieldInputLocked(this.field)||this.field.menu!==null)return {moved:false,reason:'INPUT_LOCKED'};return this.operation(async()=>{const v=vector(facing);if(!v)throw Error('Invalid direction');const s=this.snapshot(),from=positionCell(s.position),to={x:from.x+v[0],y:from.y+v[1]},position=cellPosition(this.map.id,to.x,to.y,facing);if(!coreWalkable(this.field,position.x,position.y)){await this.story.worldCommand({type:'face',facing});return {moved:false,reason:'COLLISION'}}await this.story.worldCommand({type:'move',...to,facing});this.field.walk+=GRID;this.field.moving=true;const speciesNo=this.definition.roamingNodeApproval==='APPROVED'&&this.story.roamingAt?.(this.map.id,to.x,to.y);if(speciesNo){const roaming=await this.story.runRoamer(speciesNo,this.options());return {moved:true,encounter:true,roaming}}const z=zoneAt(this.map,to.x,to.y);if(!z)return {moved:true,encounter:false};if(z.policyExcluded)return {moved:true,eligible:false,reason:'POLICY_NO_RANDOM_ENCOUNTER'};await this.story.enterArea(z.areaId,z.method);return {moved:true,...await this.story.encounterStep({from,to,serial:this.snapshot().encounter.movementSerial+1,areaId:z.areaId,method:z.method,eligible:true,moved:true,blocked:false,position},this.options())}})}
 nearby(){return this.map.points.map(id=>this.definition.points[id]).filter(p=>pointDistance(this.snapshot().position,p)<=1)}
 async interact(id,a={}){const p=this.definition.points[id];if(!p||pointDistance(this.snapshot().position,p)>1)throw Error('해당 위치 가까이에서 조사하세요.');return this.operation(async()=>{
  if(this.snapshot().enhancedLeague?.phase==='active'&&p.kind!=='enhanced-league')throw Error('강화 리그 도전을 마치거나 중도 포기한 뒤 이용하세요.');
  if(p.kind==='enhanced-league'){if(a.type==='next')return this.story.runEnhancedLeagueOpponent(this.options({attempt:a.attempt,index:a.index}));return this.story.enhancedLeagueCommand(a)}
  if(p.kind==='enhanced-league-info')return {message:'본편 챔피언 승리와 POST 해금 후 계룡산 리그 입구에서 강화 리그에 도전하세요.'};
  if(p.kind==='yeji-final'){if(!worldGate(this.snapshot(),this.story.contract,p.gate))throw Error('YEJI_FINAL_GATE_LOCKED');return this.story.runYejiFinal(this.options())}
  if(p.kind==='route-checkpoint'){await this.story.worldCommand({type:'interaction',pointId:id});return {message:p.message}}
  if(p.kind==='harin-rematch'){if(a.type!=='challenge')return {message:'하린: 센터에서 준비한 뒤 다시 대결해 볼래?'};return this.story.runHarinRematch(this.options({sequence:a.sequence}))}
  if(p.kind==='warp'){if(p.exit&&!this.snapshot().progress.completedStages.includes(p.stageId))await this.story.completeStage(p.stageId);if(!worldStageAccess(this.snapshot(),this.story.contract,this.definition.maps[p.targetMapId].stageId)||!worldGate(this.snapshot(),this.story.contract,p.gate))throw Error('WORLD_GATE_LOCKED');await this.story.worldCommand({type:'warp',pointId:id});unlockField(this.field);return}
  if(p.kind==='puzzle'){await this.story.worldCommand({type:'puzzle',pointId:id});return {message:this.snapshot().world.puzzles.includes(p.puzzleId)?'관장 통로가 열려 있습니다. 북쪽 관장을 만난 뒤 같은 입구로 돌아갈 수 있어요.':p.message}}if(p.kind==='landmark'&&p.message){await this.story.worldCommand({type:'interaction',pointId:id});return {message:p.message}}if(p.kind==='event')return this.story.runEvent(p.eventId,this.options());if(p.kind==='trainer'){const trainer=this.story.contract.trainers[p.trainerId];if(!trainer?.repeatable&&this.snapshot().progress.defeatedTrainers.includes(p.trainerId)){const actor=this.field.core.npcs.find(n=>n.canonicalTrainerId===p.trainerId);return {message:actor?.afterDialogue??'조사를 응원해요.',alreadyDefeated:true,trainerId:p.trainerId}}return this.story.runTrainer(p.trainerId,this.options())}if(p.kind==='post-deferred')throw Error(p.reason);
  if(p.kind==='tutorial'){await this.story.enterArea(p.areaId,null);return this.story.runTutorialCapture(this.options())}
  if(p.kind==='fishing'){const s=this.snapshot(),cell=positionCell(s.position);if(cell.x!==p.x||cell.y!==p.y||s.position.facing!==p.facing||!tileAt(this.map,...p.water).water)throw Error('낚시 표식 위에서 남쪽 물을 향하세요.');if(!p.rods.includes(a.rod))throw Error('Invalid fishing rod');await this.story.enterArea(p.areaId,null);return this.story.fish(a.rod,this.options())}
  if(p.kind==='acquisition'){await this.story.enterArea(p.areaId,null);if(p.requirements.includes('story_evening_survey'))await this.story.surveyAcquisition(p.acquisitionId);return this.story.acquire(p.acquisitionId,this.options({tradeInstanceId:a.tradeInstanceId}))}if(p.kind==='compass')return this.story.assembleCompass();
  if(p.kind==='hidden-geoje'){const claimed=!!this.snapshot().geojeHidden?.receipts[p.slotId];await this.story.worldCommand({type:'hidden-geoje',pointId:id});return {message:claimed?'이미 조사한 보관함입니다.':'거제볼 1개를 발견했습니다!'}}
  if(p.kind==='hidden-marker'){await this.story.worldCommand({type:'hidden-marker',pointId:id});return {message:p.message}}
  if(['hidden-clue','hidden-hint-npc'].includes(p.kind)){await this.story.worldCommand({type:'interaction',pointId:id});return {message:p.message}}
  if(p.kind==='shop'){if(!activeEconomyPolicy(this.snapshot(),this.catalog)){quotePurchase(this.snapshot(),this.catalog.itemContract,a.itemId,a.quantity);throw Error('일반 세션의 자금·재고 정책은 승인 대기입니다.')}return this.story.economyCommand({type:'purchase',transactionId:a.transactionId,hubId:p.hubId,itemId:a.itemId,quantity:a.quantity})}
  if(p.kind==='heal'){if(a.type==='storage-exchange')return this.story.worldCommand({type:a.type,pointId:id,partyInstanceId:a.partyInstanceId,boxInstanceId:a.boxInstanceId});if(!a.type||a.type==='heal'){await this.story.worldCommand({type:'visit-hub',pointId:id});return activeEconomyPolicy(this.snapshot(),this.catalog)?this.story.economyCommand({type:'heal',transactionId:a.transactionId,hubId:p.hubId}):this.story.recoverParty()}if(!['ball-aid','research-accept','research-report'].includes(a.type))throw Error('Unknown center action');return this.story.economyCommand({type:a.type,hubId:p.hubId,transactionId:a.transactionId,round:a.round})}
  if(p.kind==='research')return this.story.economyCommand({type:'observe',transactionId:a.transactionId,pointId:id,round:this.snapshot().economy.quest.round});return this.story.worldCommand({type:'interaction',pointId:id});
 },{resetActors:true})}
 tick(dt){if(!this.busy)tickFieldCore(this.field,dt,this.animation,false)}
 continueTrainerDialogue(){if(this.field.core.sequence?.kind==='trainer'&&this.field.core.sequence.phase==='dialogue'){this.field.dialogue=[];endNPCDialogue(this.field);return true}return false}
 async startDetectedBattle(){if(this.busy||!this.field.core.battleReady)return null;const n=this.field.core.npcs.find(n=>n.id===this.field.core.pendingBattle?.trainerId);if(!n?.canonicalTrainerId){unlockField(this.field);return null}return this.operation(()=>this.story.runTrainer(n.canonicalTrainerId,this.options()),{resetActors:true,allowFieldSequence:true})}
 async useItem(itemId,instanceId,transactionId,moveSlot=null){return this.operation(()=>this.story.economyCommand({type:'use-item',itemId,instanceId,transactionId,...(moveSlot===null?{}:{moveSlot})}))}
 async reorderLeagueParty(instanceIds){return this.operation(()=>this.story.enhancedLeagueCommand({type:'reorder',instanceIds}))}
 async evolve(instanceId){return this.operation(()=>this.story.evolve(instanceId))}actBattle(a){return this.story.actBattle(a)}dispose(){this.disposer()}
}
